"""Public scalar stack-value transport over two exact owned static exports."""
import base64,zlib,json,copy,dataclasses,sys
import pytest
from aether_re.ghidra_headless_bridge import GhidraFunctionInfo,GhidraDecompilationResult
MODEL='bounded-ms-x64-stack-values.v1'
BUNDLES=json.loads(zlib.decompress(base64.b64decode('')))

def export_case(tmp_path,index=0):
 item=copy.deepcopy(BUNDLES[index]);target=tmp_path/'owned-static.dll';target.write_bytes(base64.b64decode(item['binary']))
 fields={f.name for f in dataclasses.fields(GhidraFunctionInfo) if f.init}
 info=GhidraFunctionInfo(**{k:v for k,v in item['info'].items() if k in fields})
 return GhidraDecompilationResult(str(target),True,1,1,{info.function_id:info},'','',0,target_sha256=item['target'],status='complete')

@pytest.mark.parametrize('index',[0,1],ids=['Od','O2'])
def test_new_profile_reconstructs_six_observed_formals_without_abi_claim(tmp_path,index):
 report=export_case(tmp_path,index).select_reconstruction('owned_sum6',memory_model='bounded-bytes.v2',call_model=MODEL)
 assert report['status']=='complete',report
 assert report['call_model']['schema']==MODEL and len(report['input_bindings'])==6
 proof=report['call_model']['functions'][0]['stack_parameter_proof']
 assert proof['formal_count']==6 and len(proof['stack_inputs'])==2
 assert report['abi_recovered'] is report['binary_equivalence_proved'] is False
 assert len(report['runtime_parameters'])==3
 assert any('immutable supplied 64-bit values' in h for h in report['call_model']['hypotheses'])

@pytest.mark.parametrize('model',['bounded-direct-pure-calls.v1','bounded-direct-effects-calls.v1'])
def test_old_profiles_keep_the_stack_input_refusal(tmp_path,model):
 report=export_case(tmp_path).select_reconstruction('owned_sum6',memory_model='bounded-bytes.v2',call_model=model)
 assert report['status']=='unsupported' and 'stack_input_unmodeled' in report['errors'][0]

def test_mcp_advertises_explicit_stack_profile():
 from aether_re.mcp_server import TOOLS
 tool=next(t for t in TOOLS if t['name']=='aether_ghidra_decompile')
 assert MODEL in tool['inputSchema']['properties']['call_model']['enum']

@pytest.mark.parametrize('command,flag,handler',[('ghidra-decompile','--call-model','cmd_ghidra_decompile'),('universal','--native-call-model','cmd_universal')])
def test_cli_accepts_new_profile(monkeypatch,tmp_path,command,flag,handler):
 import megazord
 seen=[];monkeypatch.setattr(megazord,handler,lambda args:seen.append(args) or 0)
 options=[command,str(tmp_path/'owned.dll'),flag,MODEL]
 if command=='universal':options+=['--out',str(tmp_path/'case'),'--native-reconstruction','--native-memory-model','bounded-bytes.v2']
 else:options+=['--memory-model','bounded-bytes.v2','--reconstruct-function','owned_sum6']
 monkeypatch.setattr(sys,'argv',['megazord',*options]);assert megazord.main()==0 and len(seen)==1
